/** Returns the shipping cost for a given subtotal. */
public BigDecimal shippingCost(BigDecimal subtotal) {
    if (subtotal.compareTo(new BigDecimal("50.00")) >= 0) {
        return new BigDecimal("0.00");
    } else {
        return new BigDecimal("4.99");
    }
}

